import * as THREE from './vendor/three.module.js';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function colliderWorldMatrix(root,object,part){root.updateMatrixWorld(true);return root.matrixWorld.clone().multiply(new THREE.Matrix4().makeRotationFromQuaternion(new THREE.Quaternion().fromArray(object.rightRotation||[0,0,0,1]))).multiply(new THREE.Matrix4().compose(new THREE.Vector3().fromArray(part.c),new THREE.Quaternion().fromArray(part.q),new THREE.Vector3().fromArray(part.s)));}
export function colliderDragEntry(root,object,part){const frame=root.matrixWorld.clone().multiply(new THREE.Matrix4().makeRotationFromQuaternion(new THREE.Quaternion().fromArray(object.rightRotation||[0,0,0,1]))),q=root.quaternion.clone().multiply(new THREE.Quaternion().fromArray(object.rightRotation||[0,0,0,1]));return {id:object.id,part:structuredClone(part),inverse:frame.invert(),orientation:q};}
export function applyColliderDrag(entry,mode,delta,part){const start=entry.part;if(mode==='translate'){const world=new THREE.Vector3(...start.c).applyMatrix4(entry.inverse.clone().invert()).add(delta.position);part.c=world.applyMatrix4(entry.inverse).toArray().map(v=>clamp(v,-8,8));}else if(mode==='rotate'){const local=entry.orientation.clone().invert().multiply(delta.rotation).multiply(entry.orientation);part.q=local.multiply(new THREE.Quaternion().fromArray(start.q)).normalize().toArray();}else{part.s=start.s.map((v,i)=>clamp(v*delta.scale[i],.0001,16));}return part;}
